SELECT id, tenant_id, plan_revision_id, role_code, person_name, duty_description, phone, arrive_time, version, creator, create_time, updater, update_time, deleted, current_support_contact_change_id, customer_contact_id, customer_contact_version, sort_order FROM cut_cutover_support_arrangement WHERE tenant_id = #{query.tenantId}
  AND plan_revision_id = #{query.planRevisionId} AND deleted = b'0'
ORDER BY sort_order, id ASC

SELECT id, tenant_id, plan_revision_id, role_code, person_name, duty_description, phone, arrive_time, version, creator, create_time, updater, update_time, deleted, current_support_contact_change_id, customer_contact_id, customer_contact_version, sort_order FROM cut_cutover_support_arrangement WHERE tenant_id = #{query.tenantId}
  AND plan_revision_id = #{query.planRevisionId} AND deleted = b'0'
ORDER BY sort_order, id ASC FOR UPDATE

mapper.update:
UPDATE cut_cutover_support_arrangement arrangement
JOIN cut_plan_revision plan ON plan.id = arrangement.plan_revision_id AND plan.tenant_id = arrangement.tenant_id
SET arrangement.current_support_contact_change_id = #{query.change.id},
    arrangement.updater = #{query.change.operateUserId}, arrangement.update_time = #{query.change.operateTime},
    arrangement.version = arrangement.version + 1
WHERE arrangement.tenant_id = #{query.baseline.tenantId} AND arrangement.id = #{query.baseline.id}
  AND arrangement.plan_revision_id = #{query.plan.id} AND arrangement.version = #{query.baseline.version}
  AND arrangement.current_support_contact_change_id <=> #{query.baseline.currentSupportContactChangeId}
  AND arrangement.deleted = b'0' AND plan.deleted = b'0' AND plan.status_code = 'SUBMITTED'
  AND plan.current_marker = 1 AND plan.version = #{query.expectedPlanVersion} AND plan.approval_instance_id IS NOT NULL
